class TestDockerRuntime:
    
    def test_init_failure(self):
        with patch('docker.from_env', side_effect=Exception("Daemon not found")):
            with pytest.raises(RuntimeNotFoundError):
                DockerRuntime()

    @pytest.mark.asyncio
    async def test_pull_image_success(self, mock_docker_client):
        runtime = DockerRuntime()
        await runtime.pull_image("alpine")
        mock_docker_client.images.pull.assert_called_once_with("alpine")

    @pytest.mark.asyncio
    async def test_pull_image_failure(self, mock_docker_client):
        mock_docker_client.images.pull.side_effect = Exception("Network Error")
        runtime = DockerRuntime()
        with pytest.raises(ContainerExecutionError, match="Image pull failed"):
            await runtime.pull_image("alpine")

    @pytest.mark.asyncio
    async def test_run_container_success(self, mock_docker_client):
        # Setup Mock Container
        mock_container = MagicMock()
        mock_container.id = "cont_123"
        mock_container.status = 'exited'
        mock_container.attrs = {'State': {'ExitCode': 0}}
        mock_container.logs.return_value = b"Hello World"
        mock_container.stats.return_value = {
            "memory_stats": {"max_usage": 1024},
            "cpu_stats": {"cpu_usage": {"total_usage": 500}}
        }
        
        mock_docker_client.containers.run.return_value = mock_container
        
        runtime = DockerRuntime()
        limits = ResourceLimits(cpu_cores=1.0, memory_mb=512)
        mounts = [VolumeMount(source="/src", target="/dst")]
        
        result = await runtime.run_container(
            "alpine", ["ls"], {}, limits, mounts, "bridge", 10
        )
        
        assert result.status == ExecutionStatus.COMPLETED
        assert result.exit_code == 0
        assert result.stdout == "Hello World"
        assert result.metrics["peak_memory_bytes"] == 1024
        mock_container.remove.assert_called_once()

    @pytest.mark.asyncio
    async def test_run_container_timeout(self, mock_docker_client):
        mock_container = MagicMock()
        mock_container.id = "cont_timeout"
        mock_container.status = 'running' # Never exits
        
        mock_docker_client.containers.run.return_value = mock_container
        
        runtime = DockerRuntime()
        # Set a very short timeout for the test
        result = await runtime.run_container(
            "alpine", ["sleep", "100"], {}, ResourceLimits(), [], "bridge", 1
        )
        
        assert result.status == ExecutionStatus.TIMED_OUT
        assert result.exit_code == -1
        mock_container.kill.assert_called_once()

    @pytest.mark.asyncio
    async def test_run_container_oom_crash(self, mock_docker_client):
        mock_container = MagicMock()
        mock_container.id = "cont_oom"
        mock_container.status = 'exited'
        mock_container.attrs = {'State': {'ExitCode': 137}} # OOM Exit Code
        mock_container.logs.return_value = b""
        mock_container.stats.return_value = {}
        
        mock_docker_client.containers.run.return_value = mock_container
        
        runtime = DockerRuntime()
        result = await runtime.run_container(
            "alpine", ["malloc_lots"], {}, ResourceLimits(), [], "bridge", 10
        )
        
        assert result.status == ExecutionStatus.CRASHED
        assert result.exit_code == 137

