@pytest.mark.asyncio
async def test_volume_mount_conversion(mock_docker_client):
    """Verify that VolumeMount objects are correctly converted to Docker SDK format."""
    mock_container = MagicMock()
    mock_container.status = 'exited'
    mock_container.attrs = {'State': {'ExitCode': 0}}
    mock_container.logs.return_value = b""
    mock_container.stats.return_value = {}
    mock_docker_client.containers.run.return_value = mock_container
    
    runtime = DockerRuntime()
    mounts = [
        VolumeMount(source="/host/a", target="/cont/a", read_only=True),
        VolumeMount(source="/host/b", target="/cont/b", read_only=False)
    ]
    
    await runtime.run_container("alpine", ["ls"], {}, ResourceLimits(), mounts, "bridge", 10)
    
    # Extract the volumes argument from the call to containers.run
    args, kwargs = mock_docker_client.containers.run.call_args
    volumes = kwargs.get('volumes')
    
    assert volumes["/host/a"] == {'bind': '/cont/a', 'mode': 'ro'}
    assert volumes["/host/b"] == {'bind': '/cont/b', 'mode': 'rw'}